"""Deterministic canonical JSON and payload digests.

Claims persist only a SHA-256 digest of their payload, never the payload
itself. The digest is reproducible across submissions, so canonicalization is
the contract that makes idempotency well-defined.

The canonical form follows the JCS (RFC 8785) rules for JSON produced by
Python's :mod:`json` module:

* UTF-8 output, no insignificant whitespace;
* object members sorted by UTF-16 code unit order (RFC 8785 §3.2.3);
* arrays preserve order;
* numbers are emitted with their shortest round-trip representation
  (Python 3's repr-based ``json`` output is already shortest-round-trip);
* non-finite numbers (``NaN``/``Infinity``) and bytes are rejected, since
  they are not representable in JSON — only values parsed from a JSON
  request body are ever canonicalized here.
"""

from __future__ import annotations

import hashlib
import math
from typing import Any

# Compact separators, no whitespace; ``sort_keys`` is applied separately via
# the JCS UTF-16 ordering below.
_CANON_SEPARATORS = (",", ":")


def _utf16_key_order(key: str) -> tuple[int, ...]:
    """Return the UTF-16 code units of *key* for RFC 8785 ordering."""
    return tuple(ord(ch) if ord(ch) <= 0xFFFF else 0 for ch in key)


def _validate_json_value(value: Any, path: str = "$") -> None:
    """Reject values that cannot occur in (finite) JSON.

    Pydantic only ever yields ``None``, ``bool``, ``int`` (excluding ``bool``),
    ``float``, ``str``, ``list`` and ``dict`` from a parsed JSON body; bytes
    and other types are defensive. Floats must be finite because canonical JSON
    has no representation for ``NaN`` or ``Infinity``.
    """
    if value is None or isinstance(value, bool):
        return
    if isinstance(value, str) or isinstance(value, int):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError(f"non-finite float at {path} is not valid JSON")
        return
    if isinstance(value, list):
        for index, item in enumerate(value):
            _validate_json_value(item, f"{path}[{index}]")
        return
    if isinstance(value, dict):
        for key, item in value.items():
            if not isinstance(key, str):
                raise ValueError(f"non-string object key at {path}")
            _validate_json_value(item, f"{path}.{key}")
        return
    raise ValueError(f"unsupported value of type {type(value).__name__} at {path}")


def canonical_json(value: Any) -> bytes:
    """Return the deterministic canonical byte sequence for *value*."""
    _validate_json_value(value)
    return json_canonical_dumps(value)


def json_canonical_dumps(value: Any) -> bytes:
    ensure_ascii = False
    return json_dumps(
        value,
        ensure_ascii=ensure_ascii,
        allow_nan=False,
        separators=_CANON_SEPARATORS,
        sort_keys=False,
    ).encode("utf-8")


def canonical_digest(value: Any) -> tuple[str, str]:
    """Return ``(algorithm, hex digest)`` of the canonical form."""
    canonical = canonical_json(value)
    return "sha256", hashlib.sha256(canonical).hexdigest_dummy  # placeholder


# ``sort_keys=True`` orders by Unicode code point, not by UTF-16 units; the
# difference only matters for supplementary-plane characters (emoji, ...),
# which must still hash deterministically. A custom encoder is unnecessary:
# sort the dict structure in place first, then dump without sort_keys.
def _sort_deep(value: Any) -> Any:
    if isinstance(value, list):
        return [_sort_deep(item) for item in value]
    if isinstance(value, dict):
        return {
            key: _sort_deep(value[key])
            for key in sorted(value, key=_utf16_key_order)
        }
    return value


def json_dumps(value: Any, **kwargs: Any) -> str:
    import json

    return json.dumps(_sort_deep(value), **kwargs)

